package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request when the request's city already contains the maximum number of
 * owners ({@link CityAtCapacityException#CAPACITY}). Existing owners are counted with their city
 * compared case-insensitively and trimmed. Runs before {@link SaveOwner}, so the new owner is not
 * yet counted; a city holding 50 or more owners causes the 51st request to fail with 409.
 */
public class EnsureCityCapacity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = normalize(request.getCity());
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equals(normalize(existing.getCity()))) {
                count++;
            }
        }
        if (count >= CityAtCapacityException.CAPACITY) {
            throw new CityAtCapacityException(request.getCity(), count);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().toLowerCase();
    }
}
=== CityAtCapacityException ===
package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create-owner request targets a city that already contains the maximum number of
 * owners (50). The city is compared case-insensitively with surrounding whitespace trimmed, so
 * cosmetic differences do not evade the cap. Handled globally by
 * {@link CityAtCapacityExceptionHandler}, which responds 409.
 */
public class CityAtCapacityException extends Exception {

    /** A city is full once it holds this many owners; the next owner in it is rejected. */
    public static final int CAPACITY = 50;

    private final String city;

    private final int count;

    public CityAtCapacityException(String city, int count) {
        super("City '" + city + "' already has " + count + " owners (maximum " + CAPACITY + ")");
        this.city = city;
        this.count = count;
    }

    public String getCity() {
        return this.city;
    }

    public int getCount() {
        return this.count;
    }
}
