1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
15	 * firstName, lastName, address, city or telephone. A whitespace-only value counts as blank, which
16	 * bean validation alone does not catch for the pattern-less address/city fields, so the check is
17	 * explicit here. The address is normalized first (see {@link OwnerAddress}) and the required-field
18	 * check rejects an address that is blank after normalization; the normalized value is written back
19	 * so it is stored, returned and used for every later address comparison. The telephone is then
20	 * normalized to E.164 form (see {@link OwnerTelephone}); the
21	 * normalized value is written back so it is stored and returned, and a value that cannot form valid
22	 * E.164 is a 400. The
23	 * optional email, when present, must be a syntactically valid address and is normalized to lower
24	 * case; a present-but-invalid email is a 400. On success it republishes the body for {@link BuildOwner}.
25	 */
26	public class ValidateOwnerFields {
27	
28	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
29	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
30	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
31	        List<String> missing = new ArrayList<>();
32	        require("firstName", request.getFirstName(), missing);
33	        require("lastName", request.getLastName(), missing);
34	        require("address", request.getAddress(), missing);
35	        require("city", request.getCity(), missing);
36	        require("telephone", request.getTelephone(), missing);
37	        if (!missing.isEmpty()) {
38	            throw new MissingOwnerFieldsException(missing);
39	        }
40	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
41	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
42	        validated.set(request);
43	    }
44	
45	    private static void require(String field, String value, List<String> missing) {
46	        if (value == null || value.isBlank()) {
47	            missing.add(field);
48	        }
49	    }
50	}
