1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request when an existing owner already has the same lastName and the same
11	 * address. The lastName is compared case-insensitively with whitespace collapsed; the address is
12	 * compared using its normalized form (see {@link OwnerAddress}), so cosmetic differences and
13	 * abbreviation variants do not hide a shared household. A request that opts
14	 * in with {@code sharesHousehold: true} bypasses the check. On a match it throws
15	 * {@link DuplicateHouseholdException}, handled globally as 409.
16	 */
17	public class EnsureHouseholdUnique {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String lastName = normalize(request.getLastName());
25	        String address = OwnerAddress.normalize(request.getAddress());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (lastName.equals(normalize(existing.getLastName()))
28	                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
29	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
30	            }
31	        }
32	    }
33	
34	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
40	    }
41	}
