5	/**
6	 * Normalizes an owner {@code address} to a canonical form. Surrounding and repeated internal
7	 * whitespace is trimmed and collapsed to a single space, the value is upper-cased, and common
8	 * street-type abbreviations are expanded as whole words: {@code ST -> STREET}, {@code RD -> ROAD},
9	 * {@code AVE -> AVENUE}. So {@code '  12  main  st '} becomes {@code '12 MAIN STREET'} and
10	 * {@code '7 elm ave'} becomes {@code '7 ELM AVENUE'}. A null or whitespace-only value normalizes to
11	 * the empty string. The normalized value is what is stored, returned, and compared — for the
12	 * required-field check, household duplicate detection and the shared household id.
13	 */
14	final class OwnerAddress {
15	
16	    /** Whole-word street-type abbreviations expanded to their full form. */
17	    private static final Map<String, String> ABBREVIATIONS = Map.of(
18	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
19	
20	    private OwnerAddress() {
21	    }
22	
23	    /**
24	     * @return the address trimmed, whitespace-collapsed, upper-cased and with abbreviations
25	     *         expanded, or the empty string when the value is null or blank.
26	     */
27	    static String normalize(String address) {
28	        if (address == null) {
29	            return "";
30	        }
31	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        StringBuilder sb = new StringBuilder(collapsed.length());
37	        for (int i = 0; i < tokens.length; i++) {
38	            if (i > 0) {
39	                sb.append(' ');
40	            }
41	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
42	        }
43	        return sb.toString();
44	    }
45	}
